#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
};

class LinkedStack {
private:
    Node* topNode;
public:
    LinkedStack() {
        topNode = nullptr;
    }
    bool isEmpty() {
        return topNode == nullptr;
    }
    void push(int value) {
        Node* newNode = new Node();
        newNode->data = value;
        newNode->next = topNode;
        topNode = newNode;
    }
    int pop() {
        if (isEmpty()) {
            cout << "Stack is empty!" << endl;
            return -1;
        }
        Node* temp = topNode;
        int value = temp->data;
        topNode = topNode->next;
        delete temp;
        return value;
    }
    int peek() {
        if (isEmpty()) {
            return -1;
        }
        return topNode->data;
    }
};

int main() {
    LinkedStack s;
    s.push(5);
    s.push(15);
    s.push(25);
    cout << "Top: " << s.peek() << endl;
    cout << "Popped " << s.pop() << endl;
    cout << "Popped " << s.pop() << endl;
    cout << "Popped " << s.pop() << endl;
    if (s.isEmpty()) {
        cout << "The stack is empty again" << endl;
    }
    return 0;
}
